#' Patient Follow-Up & Response Guide
#'
#' An interactive guide to the patient follow-up and tumour response analyses 
#' in ClinicoPath. The choice between them is decided almost entirely by the 
#' SHAPE of your data - one value per patient, one per visit, or one per 
#' lesion per visit - so this guide starts there, shows a worked layout for 
#' each, and states plainly what each analysis can and cannot do. No data or 
#' variables required.
#' 
#' @param showOverview Show the decision table mapping data shape to analysis
#' @param showDataStructures Show an example table for each accepted data
#'   layout
#' @param showLimitations Show the limitations and known gaps of each analysis
#' @param showRecistRules Show the response criteria the RECIST analyses apply
#' @param showGlossary Show a glossary of response-assessment terms
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$overview} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$dataStructures} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$limitations} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$recistRules} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$glossary} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' @export
patientfollowupintro <- function(
    showOverview = TRUE,
    showDataStructures = TRUE,
    showLimitations = TRUE,
    showRecistRules = FALSE,
    showGlossary = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("patientfollowupintro requires jmvcore to be installed (restart may be required)")


    options <- patientfollowupintroOptions$new(
        showOverview = showOverview,
        showDataStructures = showDataStructures,
        showLimitations = showLimitations,
        showRecistRules = showRecistRules,
        showGlossary = showGlossary)

    analysis <- patientfollowupintroClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

